{
    "orderDate": "{{todayDate}}",
    "processingOptions": {
        "runBilling": true,
        "collectPayment": false
    },
    "newAccount": {
        "name": "Acme Corp",
        "currency": "USD",
        "autoPay": false,
        "billCycleDay": 0,
        "billToContact": {
            "address1": "1051 E Hillsdale",
            "city": "Foster City",
            "country": "United States",
            "firstName": "Bella",
            "lastName": "Lawrence",
            "postalCode": "94404",
            "state": "CA",
            "workEmail": "myorder@example.com"
        }
    },
    "subscriptions": [
        {
            "orderActions": [
                {
                    "type": "CreateSubscription",
                    "triggerDates": [
                        {"name": "ContractEffective", "triggerDate": "{{todayDate}}"},
                        {"name": "ServiceActivation", "triggerDate": "{{todayDate}}"},
                        {"name": "CustomerAcceptance", "triggerDate": "{{todayDate}}"}
                    ],
                    "createSubscription": {
                        "notes": "New customer sign-up Postman",
                        "terms": {
                            "initialTerm": {"period": 12, "periodType": "Month", "termType": "TERMED"},
                            "renewalSetting": "RENEW_WITH_SPECIFIC_TERM",
                            "renewalTerms": [{"period": 12, "periodType": "Month"}]
                        },
                        "subscribeToRatePlans": [
                            {
                                "productRatePlanId": "{{productrateplanid}}",
                                "chargeOverrides": [
                                    {
                                        "productRatePlanChargeId": "{{productrateplanchargeid}}",
                                        "pricing": {
                                            "recurringPerUnit": {
                                                "quantity": 10,
                                                "listPrice": 100
                                            }
                                        }
                                    }
                                ]
                            }
                        ]
                    }
                }
            ]
        }
    ]
}
